```python
def store_lzma2(data):
    out = bytearray()
    first = True
    i = 0
    if len(data) == 0:
        out.append(0x00)
        return bytes(out)
    while i < len(data):
        chunk = data[i:i+65536]
        out.append(0x01 if first else 0x02)
        out += (len(chunk)-1).to_bytes(2,'big')
        out += chunk
        first = False
        i += len(chunk)
    out.append(0x00)
    return bytes(out)
```

