#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "filters.h"

int main(int argc, char **argv)
{
	if (argc < 4) {
		fprintf(stderr, "bad args\n");
		return 2;
	}

	/* slurp stdin */
	size_t cap = 1 << 20, size = 0;
	uint8_t *buf = malloc(cap);
	size_t n;
	while ((n = fread(buf + size, 1, cap - size, stdin)) > 0) {
		size += n;
		if (size == cap) {
			cap *= 2;
			buf = realloc(buf, cap);
		}
	}

	int is_enc = strcmp(argv[2], "enc") == 0;

	if (strcmp(argv[1], "delta") == 0) {
		uint32_t dist = (uint32_t)strtoul(argv[3], NULL, 0);
		if (is_enc)
			delta_encode(buf, size, dist);
		else
			delta_decode(buf, size, dist);
	} else {
		uint64_t fid = strtoull(argv[3], NULL, 0);
		uint32_t start = (uint32_t)strtoul(argv[4], NULL, 0);
		int rc = is_enc ? bcj_encode(buf, size, fid, start)
				: bcj_decode(buf, size, fid, start);
		if (rc != 0) {
			fprintf(stderr, "unknown filter id\n");
			return 2;
		}
	}

	fwrite(buf, 1, size, stdout);
	free(buf);
	return 0;
}

